const htmlTemplate = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>Fall Focus</title>\n  <meta name=\"description\" content=\"A calm, seasonal task tracker for getting meaningful work done.\">\n  <style>@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Instrument+Serif:ital@0;1&display=swap');\n\n:root { --ink:#24352d; --paper:#f4f0e7; --cream:#faf8f2; --sage:#7f8f72; --rust:#b65331; --line:#d8d3c8; --muted:#777a70; }\n* { box-sizing:border-box; }\nhtml { background:var(--paper); }\nbody { margin:0; color:var(--ink); background:var(--paper); font-family:\"DM Sans\",sans-serif; }\nbutton,input,select { font:inherit; }\nbutton { color:inherit; }\nmain { min-height:100vh; }\nheader { height:82px; display:flex; align-items:center; justify-content:space-between; padding:0 clamp(24px,6vw,92px); border-bottom:1px solid var(--line); }\n.brand { display:flex; align-items:center; gap:11px; color:var(--ink); text-decoration:none; font-family:\"Instrument Serif\",serif; font-size:25px; }\n.brand i { color:var(--rust); font-weight:400; }\n.brand-mark { width:38px; height:38px; display:grid; place-items:center; color:var(--cream); background:var(--ink); border-radius:50% 50% 45% 55%; transform:rotate(-5deg); }\n.season,.eyebrow,.stat-label,.list-head,footer span { font-size:11px; font-weight:600; letter-spacing:.17em; }\n.season { display:flex; align-items:center; gap:10px; color:var(--muted); }\n.season span { width:7px; height:7px; border-radius:50%; background:var(--rust); }\n.hero { max-width:1240px; margin:auto; padding:76px 48px 63px; display:flex; align-items:flex-end; justify-content:space-between; gap:50px; }\n.eyebrow { color:var(--rust); margin:0 0 22px; }\nh1,h2 { font-family:\"Instrument Serif\",serif; font-weight:400; line-height:.91; margin:0; letter-spacing:-.025em; }\nh1 { font-size:clamp(62px,8.3vw,116px); }\nh1 em,h2 em { color:var(--rust); }\n.intro { color:var(--muted); line-height:1.7; max-width:520px; font-size:16px; margin:30px 0 0; }\n.hero-action { text-align:center; padding-bottom:10px; min-width:210px; }\n.hero-action p { font-size:12px; color:var(--muted); margin:14px 0 0; }\n.primary { display:inline-flex; align-items:center; justify-content:center; gap:10px; background:var(--ink); color:white; border:0; border-radius:2px; padding:16px 23px; cursor:pointer; transition:.2s; box-shadow:0 8px 24px #24352d22; }\n.primary:hover { background:var(--rust); transform:translateY(-2px); }\n.stats { background:var(--ink); color:white; display:grid; grid-template-columns:1.6fr repeat(3,1fr); padding:0 clamp(24px,6vw,92px); }\n.stats>div { min-height:174px; padding:31px clamp(20px,3vw,44px); border-right:1px solid #ffffff1f; display:flex; flex-direction:column; justify-content:center; }\n.stats>div:first-child { padding-left:0; }\n.stats>div:last-child { border:0; }\n.stat-label { color:#abb4ac; }\n.stats strong { font-family:\"Instrument Serif\",serif; font-size:52px; font-weight:400; line-height:1; margin-top:15px; }\n.stats strong small { font-size:25px; }\n.stats strong.rust { color:#e48562; }\n.stats p { color:#abb4ac; margin:8px 0 0; font-size:12px; }\n.bar { height:4px; max-width:360px; background:#ffffff20; margin-top:18px; }\n.bar i { display:block; background:#dd805d; height:100%; transition:width .4s; }\n.workspace { max-width:1240px; margin:0 auto; padding:62px 48px 94px; }\n.toolbar { display:flex; justify-content:space-between; gap:20px; align-items:center; margin-bottom:42px; }\n.filters { display:flex; flex-wrap:wrap; gap:4px; }\n.filters button { border:0; background:transparent; padding:9px 14px; color:var(--muted); cursor:pointer; font-size:13px; border-radius:20px; }\n.filters button.active { background:var(--ink); color:white; }\n.search { display:flex; align-items:center; gap:8px; color:var(--muted); border-bottom:1px solid var(--line); padding:8px 2px; }\n.search input { width:130px; border:0; outline:0; background:transparent; color:var(--ink); }\n.list-head { color:var(--muted); display:flex; justify-content:space-between; padding:0 0 13px; border-bottom:1px solid var(--ink); }\n.task { min-height:103px; border-bottom:1px solid var(--line); display:flex; align-items:center; gap:20px; padding:19px 10px; transition:.2s; }\n.task:hover { background:#faf8f2; padding-left:16px; }\n.check { flex:0 0 24px; width:24px; height:24px; border:1px solid #a8aea5; background:transparent; border-radius:50%; display:grid; place-items:center; cursor:pointer; }\n.completed .check { background:var(--sage); color:white; border-color:var(--sage); }\n.task-body { flex:1; }\n.task h3 { margin:0 0 11px; font-family:\"Instrument Serif\",serif; font-size:23px; font-weight:400; }\n.completed h3 { color:#8c9088; text-decoration:line-through; }\n.meta { display:flex; flex-wrap:wrap; align-items:center; gap:15px; font-size:11px; color:var(--muted); }\n.tag { text-transform:uppercase; font-weight:600; letter-spacing:.08em; padding:4px 8px; border-radius:2px; }\n.tag.work { color:#52644e; background:#dfe5d9; }.tag.planning { color:#725138; background:#eee0cf; }.tag.personal { color:#62546c; background:#e4dfe7; }\n.priority { display:flex; align-items:center; gap:6px; }\n.priority i { width:6px; height:6px; border-radius:50%; background:#a2a49f; }\n.priority.high i { background:var(--rust); }.priority.medium i { background:#c09348; }.priority.low i { background:var(--sage); }\n.date { display:flex; align-items:center; gap:6px; }\n.delete,.close { border:0; background:transparent; color:#9a9b95; cursor:pointer; padding:8px; opacity:0; transition:.2s; }\n.task:hover .delete { opacity:1; }.delete:hover,.close:hover { color:var(--rust); }\n.empty { text-align:center; color:var(--muted); padding:70px 20px; }\n.empty svg { color:var(--sage); }.empty h3 { font-family:\"Instrument Serif\",serif; color:var(--ink); font-size:25px; margin:12px 0 4px; }.empty p { margin:0; font-size:13px; }\nfooter { border-top:1px solid var(--line); min-height:88px; display:flex; justify-content:space-between; align-items:center; padding:0 clamp(24px,6vw,92px); color:var(--muted); }\nfooter p { font-family:\"Instrument Serif\",serif; font-size:18px; font-style:italic; }\n.modal-backdrop { position:fixed; inset:0; background:#18231dd9; backdrop-filter:blur(7px); display:grid; place-items:center; padding:20px; z-index:5; }\n.modal { position:relative; width:min(520px,100%); background:var(--cream); padding:42px; box-shadow:0 25px 90px #0005; animation:rise .25s ease-out; }\n@keyframes rise { from { opacity:0; transform:translateY(16px); } }\n.close { position:absolute; right:20px; top:20px; opacity:1; }\n.modal h2 { font-size:46px; margin-bottom:32px; }\n.modal label { display:block; font-size:11px; text-transform:uppercase; letter-spacing:.12em; font-weight:600; color:var(--muted); margin-top:18px; }\n.modal input,.modal select { width:100%; border:0; border-bottom:1px solid var(--line); background:transparent; color:var(--ink); outline:0; padding:11px 2px; margin-top:4px; text-transform:none; letter-spacing:0; }\n.modal input:focus,.modal select:focus { border-color:var(--rust); }\n.form-row { display:grid; grid-template-columns:1fr 1fr; gap:25px; }\n.submit { width:100%; margin-top:30px; }\n@media (max-width:760px) {\n  header { height:70px; }.season { display:none; }\n  .hero { padding:52px 24px; display:block; }.hero-action { text-align:left; margin-top:34px; }\n  .stats { grid-template-columns:1fr 1fr; padding:0 24px; }.stats>div { min-height:140px; padding:24px 14px; border-bottom:1px solid #ffffff1f; }.stats>div:first-child { padding-left:14px; }.stats strong { font-size:42px; }\n  .workspace { padding:45px 24px 70px; }.toolbar { align-items:flex-start; flex-direction:column; }.search { width:100%; }.search input { width:100%; }\n  .task { gap:12px; }.task h3 { font-size:20px; }.delete { opacity:1; }\n  footer { justify-content:center; }footer span { display:none; }.modal { padding:35px 25px; }.modal h2 { font-size:39px; }\n}\n\n  .brand-mark{font-size:18px}.add-form{display:grid;gap:18px}.add-form h2{font-family:\"Instrument Serif\",serif;font-size:46px;font-weight:400;line-height:.95;margin:0 0 8px}.add-form label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.12em;font-weight:600;color:var(--muted)}.add-form input,.add-form select{width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);outline:0;padding:11px 2px;margin-top:4px}.add-form input:focus,.add-form select:focus{border-color:var(--rust)}.modal[hidden]{display:none}.modal{display:block}.leaf-icon{font-size:22px}.check{font-size:14px}.search span{font-size:17px}.delete{font-size:18px}.account{display:flex;align-items:center;gap:12px}.account button{border:1px solid var(--line);background:transparent;padding:8px 12px;cursor:pointer;font-size:12px}.sync{font-size:11px;color:var(--muted)}.sync.online{color:var(--sage)}.auth-note{color:var(--muted);font-size:13px;line-height:1.6;margin:0}.auth-message{font-size:13px;color:var(--rust);min-height:20px}.loading{opacity:.55;pointer-events:none}@media(max-width:760px){.account .sync{display:none}}</style>\n</head>\n<body>\n<main>\n  <header>\n    <a class=\"brand\" href=\"#\"><span class=\"brand-mark\">⌁</span><span>Fall <i>Focus</i></span></a>\n    <div class=\"account\"><span class=\"sync\" id=\"sync-status\">Sign in to sync</span><button id=\"account-button\">Sign in</button></div>\n  </header>\n  <section class=\"hero\">\n    <div>\n      <p class=\"eyebrow\">YOUR SEASON, CLEARLY PLANNED</p>\n      <h1>Make space for<br><em>what matters.</em></h1>\n      <p class=\"intro\">A simple home for the work you want to finish this fall. One task, one week, one win at a time.</p>\n    </div>\n    <div class=\"hero-action\">\n      <button class=\"primary\" id=\"open-form\">＋ Add a task</button>\n      <p id=\"open-caption\"></p>\n    </div>\n  </section>\n  <section class=\"stats\" aria-label=\"Task summary\">\n    <div><span class=\"stat-label\">SEASON PROGRESS</span><strong><span id=\"progress\">0</span><small>%</small></strong><div class=\"bar\"><i id=\"progress-bar\"></i></div></div>\n    <div><span class=\"stat-label\">OPEN TASKS</span><strong id=\"open-count\">0</strong><p>Still in motion</p></div>\n    <div><span class=\"stat-label\">COMPLETED</span><strong id=\"done-count\">0</strong><p>Wins this fall</p></div>\n    <div><span class=\"stat-label\">HIGH PRIORITY</span><strong class=\"rust\" id=\"high-count\">0</strong><p>Needs attention</p></div>\n  </section>\n  <section class=\"workspace\">\n    <div class=\"toolbar\">\n      <div class=\"filters\" id=\"filters\"></div>\n      <label class=\"search\"><span>⌕</span><input id=\"search\" placeholder=\"Search tasks\"></label>\n    </div>\n    <div class=\"list-head\"><span>TO DO</span><span id=\"item-count\"></span></div>\n    <div class=\"task-list\" id=\"task-list\"></div>\n  </section>\n  <footer><span>FALL FOCUS</span><p>Small progress is still progress.</p><span>EST. 2026</span></footer>\n  <div class=\"modal-backdrop modal\" id=\"modal\" hidden>\n    <form class=\"modal add-form\" id=\"task-form\">\n      <button type=\"button\" class=\"close\" id=\"close-form\" aria-label=\"Close\">×</button>\n      <p class=\"eyebrow\">A FRESH START</p>\n      <h2>Add something<br><em>worth finishing.</em></h2>\n      <label>Task name<input id=\"title\" required placeholder=\"What needs to get done?\"></label>\n      <div class=\"form-row\">\n        <label>Category<select id=\"category\"><option>Work</option><option>Planning</option><option>Personal</option></select></label>\n        <label>Priority<select id=\"priority\"><option>High</option><option selected>Medium</option><option>Low</option></select></label>\n      </div>\n      <label>Due date<input id=\"due\" type=\"date\" required value=\"2026-09-01\"></label>\n      <button class=\"primary submit\" type=\"submit\">＋ Add task</button>\n    </form>\n  </div>\n  <div class=\"modal-backdrop modal\" id=\"auth-modal\" hidden>\n    <form class=\"modal add-form\" id=\"auth-form\">\n      <button type=\"button\" class=\"close\" id=\"close-auth\" aria-label=\"Close\">×</button>\n      <p class=\"eyebrow\">SYNC EVERYWHERE</p>\n      <h2>Your fall list,<br><em>on every device.</em></h2>\n      <p class=\"auth-note\">Enter your email and we’ll send a secure sign-in link. Use the same email on each device.</p>\n      <label>Email address<input id=\"auth-email\" type=\"email\" required placeholder=\"you@example.com\"></label>\n      <p class=\"auth-message\" id=\"auth-message\"></p>\n      <button class=\"primary submit\" type=\"submit\">Email me a sign-in link</button>\n    </form>\n  </div>\n</main>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n<script>\nconst SUPABASE_URL=\"__SUPABASE_URL__\",SUPABASE_KEY=\"__SUPABASE_PUBLISHABLE_KEY__\";\nconst cloud=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);\nconst seed=[\n {id:1,title:\"Finish project proposal\",category:\"Work\",priority:\"High\",due:\"2026-09-12\",done:false},\n {id:2,title:\"Schedule fall check-in\",category:\"Planning\",priority:\"Medium\",due:\"2026-09-18\",done:false},\n {id:3,title:\"Organize research notes\",category:\"Personal\",priority:\"Low\",due:\"2026-10-02\",done:true},\n {id:4,title:\"Prepare quarterly review\",category:\"Work\",priority:\"High\",due:\"2026-10-09\",done:false},\n {id:5,title:\"Plan November priorities\",category:\"Planning\",priority:\"Medium\",due:\"2026-10-28\",done:false}\n];\nlet tasks=[],filter=\"All\",query=\"\",user=null,channel=null;\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst date=s=>new Intl.DateTimeFormat(\"en-US\",{month:\"short\",day:\"numeric\"}).format(new Date(s+\"T12:00:00\"));\nfunction localTasks(){try{return JSON.parse(localStorage.getItem(\"fall-focus-tasks\"))||seed}catch{return seed}}\nfunction setSync(text,online=false){$(\"#sync-status\").textContent=text;$(\"#sync-status\").classList.toggle(\"online\",online)}\nasync function loadTasks(){\n if(!user){tasks=localTasks();render();return}\n setSync(\"Syncing…\");\n const {data,error}=await cloud.from(\"tasks\").select(\"*\").order(\"created_at\",{ascending:false});\n if(error){setSync(\"Sync error\");console.error(error);return}\n tasks=data;\n if(!tasks.length&&!localStorage.getItem(\"fall-focus-migrated\")){\n   const old=localTasks();\n   if(old.length){const rows=old.map(({id,...t})=>({...t,user_id:user.id}));const result=await cloud.from(\"tasks\").insert(rows).select();if(!result.error)tasks=result.data}\n   localStorage.setItem(\"fall-focus-migrated\",\"1\");\n }\n setSync(\"Synced\",true);render();subscribe();\n}\nfunction subscribe(){\n if(channel)cloud.removeChannel(channel);\n channel=cloud.channel(\"task-updates\").on(\"postgres_changes\",{event:\"*\",schema:\"public\",table:\"tasks\",filter:\"user_id=eq.\"+user.id},()=>loadTasks()).subscribe();\n}\nasync function toggleTask(id){const t=tasks.find(x=>String(x.id)===String(id));if(user){await cloud.from(\"tasks\").update({done:!t.done}).eq(\"id\",id)}else{t.done=!t.done;localStorage.setItem(\"fall-focus-tasks\",JSON.stringify(tasks));render()}}\nasync function deleteTask(id){if(user){await cloud.from(\"tasks\").delete().eq(\"id\",id)}else{tasks=tasks.filter(t=>String(t.id)!==String(id));localStorage.setItem(\"fall-focus-tasks\",JSON.stringify(tasks));render()}}\nfunction render(){\n const done=tasks.filter(t=>t.done).length,open=tasks.length-done,high=tasks.filter(t=>!t.done&&t.priority===\"High\").length,progress=tasks.length?Math.round(done/tasks.length*100):0;\n $(\"#progress\").textContent=progress;$(\"#progress-bar\").style.width=progress+\"%\";$(\"#open-count\").textContent=open;$(\"#done-count\").textContent=done;$(\"#high-count\").textContent=high;\n $(\"#open-caption\").textContent=open+\" open task\"+(open===1?\"\":\"s\")+\" this season\";\n const shown=tasks.filter(t=>(filter===\"All\"||(filter===\"Open\"&&!t.done)||(filter===\"Done\"&&t.done)||t.category===filter)&&t.title.toLowerCase().includes(query)).sort((a,b)=>Number(a.done)-Number(b.done)||new Date(a.due)-new Date(b.due));\n $(\"#item-count\").textContent=shown.length+\" \"+(shown.length===1?\"ITEM\":\"ITEMS\");\n $(\"#task-list\").innerHTML=shown.length?shown.map(t=>`<article class=\"task ${t.done?\"completed\":\"\"}\">\n  <button class=\"check\" data-check=\"${t.id}\" aria-label=\"Toggle task\">${t.done?\"✓\":\"\"}</button>\n  <div class=\"task-body\"><h3>${esc(t.title)}</h3><div class=\"meta\"><span class=\"tag ${t.category.toLowerCase()}\">${t.category}</span><span class=\"priority ${t.priority.toLowerCase()}\"><i></i>${t.priority}</span><span class=\"date\">▣ ${date(t.due)}</span></div></div>\n  <button class=\"delete\" data-delete=\"${t.id}\" aria-label=\"Delete task\">×</button></article>`).join(\"\"):`<div class=\"empty\"><span class=\"leaf-icon\">⌁</span><h3>Nothing here yet</h3><p>Enjoy the breathing room, or add a new task.</p></div>`;\n document.querySelectorAll(\"[data-check]\").forEach(b=>b.onclick=()=>toggleTask(b.dataset.check));\n document.querySelectorAll(\"[data-delete]\").forEach(b=>b.onclick=()=>deleteTask(b.dataset.delete));\n}\n[\"All\",\"Open\",\"Done\",\"Work\",\"Planning\",\"Personal\"].forEach(name=>{const b=document.createElement(\"button\");b.textContent=name;b.onclick=()=>{filter=name;document.querySelectorAll(\"#filters button\").forEach(x=>x.classList.toggle(\"active\",x===b));render()};if(name===\"All\")b.className=\"active\";$(\"#filters\").append(b)});\n$(\"#search\").oninput=e=>{query=e.target.value.toLowerCase();render()};\n$(\"#open-form\").onclick=()=>{$(\"#modal\").hidden=false;setTimeout(()=>$(\"#title\").focus(),0)};\n$(\"#close-form\").onclick=()=>$(\"#modal\").hidden=true;\n$(\"#modal\").onclick=e=>{if(e.target===$(\"#modal\"))$(\"#modal\").hidden=true};\n$(\"#task-form\").onsubmit=async e=>{e.preventDefault();const task={title:$(\"#title\").value.trim(),category:$(\"#category\").value,priority:$(\"#priority\").value,due:$(\"#due\").value,done:false};if(user){const {error}=await cloud.from(\"tasks\").insert({...task,user_id:user.id});if(error){alert(\"Could not save task: \"+error.message);return}}else{tasks.unshift({...task,id:Date.now()});localStorage.setItem(\"fall-focus-tasks\",JSON.stringify(tasks));render()}e.target.reset();$(\"#due\").value=\"2026-09-01\";$(\"#modal\").hidden=true};\n$(\"#account-button\").onclick=async()=>{if(user){await cloud.auth.signOut();return}$(\"#auth-modal\").hidden=false;$(\"#auth-email\").focus()};\n$(\"#close-auth\").onclick=()=>$(\"#auth-modal\").hidden=true;\n$(\"#auth-form\").onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$(\"#auth-message\").textContent=\"Sending…\";const {error}=await cloud.auth.signInWithOtp({email:$(\"#auth-email\").value,options:{emailRedirectTo:location.origin}});$(\"#auth-message\").textContent=error?error.message:\"Check your email for the sign-in link.\";button.disabled=false};\nasync function applySession(session){user=session?.user||null;$(\"#account-button\").textContent=user?\"Sign out\":\"Sign in\";if(!user){if(channel)cloud.removeChannel(channel);setSync(\"Sign in to sync\");tasks=localTasks();render()}else{$(\"#auth-modal\").hidden=true;await loadTasks()}}\ncloud.auth.onAuthStateChange((_event,session)=>setTimeout(()=>applySession(session),0));\ncloud.auth.getSession().then(({data})=>applySession(data.session));\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    const html = htmlTemplate
      .replaceAll("__SUPABASE_URL__", env.SUPABASE_URL || "")
      .replaceAll("__SUPABASE_PUBLISHABLE_KEY__", env.SUPABASE_PUBLISHABLE_KEY || "");
    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "no-cache"
      }
    });
  }
};
